<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?= view('partials/breadcrumbs',['title'=>$request['request_number'],'subtitle'=>'Borrowing request details and workflow status.']) ?><div class="detail-grid"><section class="panel"><div class="panel-head"><div><h2>Request Details</h2><p>Submitted <?= esc(fmt_date($request['created_at'],true)) ?></p></div><?= view('partials/status_badge',['status'=>$request['status']]) ?></div><dl class="detail-list"><div><dt>Borrower</dt><dd><?= esc($request['borrower_name']) ?></dd></div><div><dt>Requested date</dt><dd><?= esc(fmt_date($request['requested_date'])) ?></dd></div><div><dt>Expected return</dt><dd><?= esc(fmt_date($request['expected_return_date'])) ?></dd></div><div><dt>Purpose</dt><dd><?= esc($request['purpose']) ?></dd></div><?php if($request['rejection_reason']): ?><div class="wide"><dt>Rejection reason</dt><dd><?= esc($request['rejection_reason']) ?></dd></div><?php endif; ?></dl><div class="table-wrap"><table><thead><tr><th>Equipment</th><th>Requested</th><th>Released</th><th>Returned</th><th>Release Condition</th><th>Return Condition</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><b><?= esc($item['equipment_name']) ?></b><small><?= esc($item['asset_code']) ?></small></td><td><?= (int)$item['quantity_requested'] ?> <?= esc($item['unit']) ?></td><td><?= (int)$item['quantity_released'] ?></td><td><?= (int)$item['quantity_returned'] ?></td><td><?= $item['condition_on_release']?view('partials/status_badge',['status'=>$item['condition_on_release']]):'—' ?></td><td><?= $item['condition_on_return']?view('partials/status_badge',['status'=>$item['condition_on_return']]):'—' ?><?php if($item['damage_notes']): ?><small><?= esc($item['damage_notes']) ?></small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><aside class="panel action-panel"><h2>Actions</h2><?php if($this->role()==='borrower'&&$request['status']==='pending'): ?><p>You may cancel this request while it is pending.</p><form method="post" action="<?= site_url('borrow-requests/'.$request['id'].'/cancel') ?>" data-confirm="Cancel borrowing request <?= esc($request['request_number'],'attr') ?>?"><?= csrf_field() ?><button class="btn danger wide" type="submit">Cancel Request</button></form><?php elseif($this->role()!=='borrower'&&$request['status']==='pending'): ?><form method="post" action="<?= site_url('borrow-requests/'.$request['id'].'/approve') ?>" data-confirm="Approve borrowing request <?= esc($request['request_number'],'attr') ?>?"><?= csrf_field() ?><button class="btn primary wide" type="submit">Approve Request</button></form><form method="post" action="<?= site_url('borrow-requests/'.$request['id'].'/reject') ?>" class="stack-form"><?= csrf_field() ?><label>Rejection Reason<textarea name="rejection_reason" required></textarea></label><button class="btn danger wide" type="submit">Reject Request</button></form><?php elseif($this->role()!=='borrower'&&$request['status']==='approved'): ?><form method="post" action="<?= site_url('borrow-requests/'.$request['id'].'/release') ?>" data-confirm="Record release for <?= esc($request['request_number'],'attr') ?>?"><?= csrf_field() ?><p>Record condition at physical release.</p><?php foreach($items as $item): ?><label><?= esc($item['equipment_name']) ?><select name="condition_on_release[<?= (int)$item['id'] ?>]"><?php foreach(config('BantayGamit')->conditions as $k=>$v): ?><option value="<?= esc($k) ?>" <?= $item['condition_on_release']===$k||(!$item['condition_on_release']&&$k==='good')?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select></label><?php endforeach; ?><button class="btn primary wide" type="submit">Record Release</button></form><?php elseif($this->role()!=='borrower'&&in_array($request['status'],['released','overdue'],true)): ?><form method="post" action="<?= site_url('borrow-requests/'.$request['id'].'/return') ?>" data-confirm="Complete the return for <?= esc($request['request_number'],'attr') ?>?"><?= csrf_field() ?><p>Inspect each item before completing the return.</p><?php foreach($items as $item): ?><div class="return-item"><b><?= esc($item['equipment_name']) ?></b><label>Return Condition<select name="condition_on_return[<?= (int)$item['id'] ?>]"><?php foreach(config('BantayGamit')->conditions as $k=>$v): ?><option value="<?= esc($k) ?>" <?= $k==='good'?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select></label><label>Damage / Loss Notes<textarea name="damage_notes[<?= (int)$item['id'] ?>]" rows="2"></textarea></label></div><?php endforeach; ?><button class="btn primary wide" type="submit">Complete Return</button></form><?php else: ?><div class="empty">No actions are available for this request.</div><?php endif; ?></aside></div><?= $this->endSection() ?>
